public int[] MaxSlidingWindowBrute(int[] nums, int k)
{
    int n = nums.Length;
    if (n == 0 || k == 0) return Array.Empty<int>();

    var result = new int[n - k + 1];

    for (int i = 0; i + k <= n; i++)
    {
        int max = int.MinValue;
        for (int j = i; j < i + k; j++)
        {
            max = Math.Max(max, nums[j]);
        }
        result[i] = max;
    }

    return result;
}

public int[] MaxSlidingWindow(int[] nums, int k)
{
    int n = nums.Length;
    if (n == 0 || k == 0) return Array.Empty<int>();

    var result = new int[n - k + 1];
    var deque = new LinkedList<int>(); // stores indices, values decreasing
    int r = 0;

    for (int i = 0; i < n; i++)
    {
        // Remove indices that have fallen out of the window
        while (deque.Count > 0 && deque.First!.Value <= i - k)
        {
            deque.RemoveFirst();
        }

        // Remove values smaller than the incoming one - they can never be the max
        while (deque.Count > 0 && nums[deque.Last!.Value] <= nums[i])
        {
            deque.RemoveLast();
        }

        deque.AddLast(i);

        // The window is full once i >= k - 1
        if (i >= k - 1)
        {
            result[r++] = nums[deque.First!.Value];
        }
    }

    return result;
}

public int[] MaxSlidingWindow(int[] nums, int k)
{
    int n = nums.Length;
    if (n == 0 || k == 0) return Array.Empty<int>();

    var result = new int[n - k + 1];
    var deque = new LinkedList<int>();
    int r = 0;

    for (int i = 0; i < n; i++)
    {
        while (deque.Count > 0 && deque.First!.Value <= i - k) deque.RemoveFirst();
        while (deque.Count > 0 && nums[deque.Last!.Value] <= nums[i]) deque.RemoveLast();

        deque.AddLast(i);
        if (i >= k - 1) result[r++] = nums[deque.First!.Value];
    }

    return result;
}
